let openedMsgWindowCount = 0;

add_setup(async () => {
  await SpecialPowers.pushPrefEnv({
    set: [
      [
        "extensions.webextensions.uuids",
        Services.prefs.getStringPref("extensions.webextensions.uuids"),
      ],
    ],
    clear: [["mail.pane_config.dynamic"], ["mail.threadpane.listview"]],
  });

  await check3PaneState(true, true);
  const tabmail = document.getElementById("tabmail");
  if (tabmail.tabInfo.length > 1) {
    info(`Will close ${tabmail.tabInfo.length - 1} tabs left over from others`);
    for (let i = tabmail.tabInfo.length - 1; i > 0; i--) {
      tabmail.closeTab(i);
    }
    is(tabmail.tabInfo.length, 1, "One tab open from start");
  }
  // Remove state information (for example position and size) for the compose and
  // message window, which might have leaked in from previous tests.
  Services.xulStore.removeDocument(
    "chrome://messenger/content/messengercompose/messengercompose.xhtml"
  );
  Services.xulStore.removeDocument(
    "chrome://messenger/content/messageWindow.xhtml"
  );
});
